package com.example.rokidkeyboardbridge;
public final class ConversationStageMotionTest{
 static int n;static void check(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){
  ConversationStageMotion.update(CharacterChoreography.LISTEN,1000);check(ConversationStageMotion.gaze(1500,false)==0,"listen toward user");long ticket=ConversationStageMotion.epoch();
  ConversationStageMotion.update(CharacterChoreography.THINK,2000);check(!ConversationStageMotion.current(ticket),"new phase invalidates old work");check(ConversationStageMotion.gaze(3200,false)<-.2f,"thinking glance away");
  float last=ConversationStageMotion.gaze(4000,false);ConversationStageMotion.update(CharacterChoreography.SPEAK,4000);check(Math.abs(ConversationStageMotion.gaze(4000,false)-last)<.001,"no answering gaze jump");check(ConversationStageMotion.gaze(4500,false)==0,"answer looks back");
  ConversationStageMotion.update(CharacterChoreography.IDLE,6000);check(ConversationStageMotion.settling(6800),"finite finish");check(!ConversationStageMotion.optional(6800,false),"settling blocks unrelated automatic pose");check(ConversationStageMotion.optional(6800,true),"manual override wins");check(!ConversationStageMotion.settling(8000),"settling expires");
  ConversationStageMotion.update(CharacterChoreography.THINK,10000);check(ConversationStageMotion.waitGain(30000)<.21,"long wait becomes restrained");check(ConversationStageMotion.gaze(30000,false)==0,"no repeated long wait glances");check(!ConversationStageMotion.optional(30000,false),"no repeated wait gestures");check(ConversationStageMotion.gaze(11500,true)==0,"quiet respected");
  check(ConversationStageMotion.meaning("この説明に『間違い』という単語があります",FullBodyPoseCatalog.Kind.NEUTRAL)==CharacterGestureLife.SETTLE,"quoted word does not trigger apology");check(ConversationStageMotion.meaning("申し訳ありません。訂正します。",FullBodyPoseCatalog.Kind.NEUTRAL)==CharacterGestureLife.CORRECT,"apology context");check(ConversationStageMotion.meaning("まず、手順を説明します。",FullBodyPoseCatalog.Kind.EXPLAIN)==CharacterGestureLife.EXPLAIN,"explanation context");check(ConversationStageMotion.meaning("確認できました。",FullBodyPoseCatalog.Kind.NEUTRAL)==CharacterGestureLife.LISTEN,"acknowledge");check(ConversationStageMotion.meaning("次の角を右へ進んでください",FullBodyPoseCatalog.Kind.EXPLAIN)==CharacterGestureLife.GUIDE,"guidance preserved");
  CharacterMotionTuning.frequency=0;check(CharacterGestureVariation.cooldown()==45000,"calm cadence");CharacterMotionTuning.frequency=2;check(CharacterGestureVariation.cooldown()==9000,"lively cadence");CharacterMotionTuning.frequency=1;
  check(CharacterArtworkSafety.geometry(256,384,512,768,260,14,25),"sampled image valid");check(!CharacterArtworkSafety.geometry(768,512,512,768,260,14,25),"wrong aspect rejected");check(!CharacterArtworkSafety.geometry(512,768,512,768,Float.NaN,14,25),"invalid anchor rejected");check(!CharacterArtworkSafety.geometry(512,768,512,768,260,14,0),"invalid calibration rejected");
  CharacterGestureLife life=new CharacterGestureLife();life.performance.mode(40000,2);life.performance.mode(41000,0);check(life.bodyClip(41500,true)<0,"finish never offers a hand again");
  CharacterChoreography.phase=CharacterChoreography.LISTEN;check(CharacterFrameCadence.delay(false,true,true)>=66,"recognition wins over gesture FPS");CharacterChoreography.phase=CharacterChoreography.THINK;check(CharacterFrameCadence.delay(false,true,false)>=83,"waiting reserves CPU");
  ConversationStageMotion.transport(false);check(ConversationStageMotion.waitGain(20000)==.15f,"offline waiting restrained");check(ConversationStageMotion.gaze(20000,false)==0,"offline is not a thinking loop");check(!ConversationStageMotion.optional(20000,false),"offline suppresses optional gestures");ConversationStageMotion.transport(true);
  ConversationStageMotion.update(CharacterChoreography.IDLE,50000);CharacterGestureVariation v=new CharacterGestureVariation();check(v.choose(0,51000,false)==0,"first wave");check(v.choose(1,52000,false)==1,"different context motion");check(v.choose(0,53000,false)==-1,"recent wave suppressed across another gesture");check(v.choose(0,53000,true)==0,"explicit repeat still wins");
  CharacterMotionTuning.frequency=0;check(FullBodyEverydayGesture.period()==180000,"calm idle period");CharacterMotionTuning.frequency=2;check(FullBodyEverydayGesture.period()==80000,"lively idle period");CharacterMotionTuning.frequency=1;check(FullBodyEverydayGesture.period()==120000,"standard cadence retained");
  System.out.println("PASS "+n+" conversation lifecycle, semantic, cadence, frequency and image safety checks");
 }
}
